import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { defineConfig } from 'vite';

// Static multi-language build: web/{en,es,pl,ru}/index.html are generated by
// web/scripts/gen-pages.mjs and share one JS/CSS bundle. Output: dist/ (or $SMA_OUT).

// /go/<slug> is answered by the API on the hub (api/server.py, counted 302). In `npm run dev` and
// `npm run preview` the same allow-list (api/go-targets.json) redirects without counting.
const goTargets = JSON.parse(readFileSync(resolve('api/go-targets.json'), 'utf8'));
const goRedirects = (req, res, next) => {
    const m = /^\/go\/([a-z0-9]+)\/?(?:\?|$)/.exec(req.url ?? '');
    if (!m) return next();
    const target = goTargets[m[1]];
    res.statusCode = target ? 302 : 404;
    if (target) res.setHeader('Location', target);
    res.end();
};

export default defineConfig({
    root: 'web',
    publicDir: 'public',
    base: '/',
    plugins: [{
        name: 'sma-go-redirects',
        configureServer: (server) => { server.middlewares.use(goRedirects); },
        configurePreviewServer: (server) => { server.middlewares.use(goRedirects); }
    }],
    build: {
        outDir: resolve(process.env.SMA_OUT || 'dist'),
        emptyOutDir: true,
        target: 'es2022',
        sourcemap: true,
        assetsInlineLimit: 0,
        rollupOptions: {
            input: {
                root: resolve('web/index.html'),
                en: resolve('web/en/index.html'),
                es: resolve('web/es/index.html'),
                pl: resolve('web/pl/index.html'),
                ru: resolve('web/ru/index.html')
            }
        }
    },
    server: {
        port: 5181,
        strictPort: true
    },
    preview: {
        port: 5182,
        strictPort: true
    }
});
